    theory: `
      <h3>საფუარი — უხილავი მცხობელი და მეღვინე</h3>
      <p>პურის ცომის მოსაზელად დიასახლისები და მცხობელები საფუარს იყენებენ. სინამდვილეში საფუარი მიკროსკოპული <strong>ერთუჯრედიანი სოკოა</strong>. საფუარი სოკოები არ ქმნიან მიცელიუმს; ისინი ცალკეული ოვალური უჯრედებია, რომლებიც ხელსაყრელ პირობებში ძალიან სწრაფად მრავლდებიან <strong>დაკვირტვით</strong>.</p>

      <h3>სპირტული დუღილი (ფერმენტაცია)</h3>
      <p>პურის, ღვინის, ლუდისა და ყველის წარმოებას საფუძვლად უდევს ბიოლოგიური პროცესი — <strong>სპირტული დუღილი (ფერმენტაცია)</strong>. უჟანგბადო (ან ჟანგბადის ნაკლებობის) პირობებში საფუარი სოკოები იკვებებიან მარტივი შაქრით (გლუკოზით) და მას გარდაქმნიან:</p>

      <div class="table-responsive">
        <div style="background:#f0fdf4; border:2px solid #16a34a; border-radius:10px; padding:16px; text-align:center; font-size:18px; font-weight:bold; color:#166534; margin:16px 0;">
          გლუკოზა (შაქარი) &nbsp; ➔ &nbsp; ეთილის სპირტი &nbsp; + &nbsp; ნახშირორჟანგი (CO₂) ↑ &nbsp; + &nbsp; ენერგია
        </div>
      </div>

      <ul>
        <li><strong>პურის ცხობაში:</strong> გამოყოფილი <strong>ნახშირორჟანგის (CO₂) აირის ბუშტუკები</strong> ცომში იჭედება, აფართოებს მას და ცომი ფუვდება (იზრდება მოცულობაში, ხდება ფოროვანი და რბილი). გამოცხობისას მაღალ ტემპერატურაზე სპირტი ორთქლდება, ხოლო საფუარი სოკოები იღუპებიან.</li>
        <li><strong>მეღვინეობაში:</strong> ყურძნის ტკბილში არსებული შაქარი საფუარის მოქმედებით გარდაიქმნება ალკოჰოლად. დაუდუღებელ ღვინოში — <strong>მაჭარში</strong> — სწორედ ნახშირორჟანგის ბუშტუკები შუშხუნებს, რადგან დუღილი ჯერ კიდევ აქტიურ ფაზაშია.</li>
      </ul>

      <h3>სოკოები ყველის წარმოებაში</h3>
      <p>ყველის წარმოებაში საფუარი სოკოები რძის შაქარს შლიან და ყველს სასიამოვნო გემოს ანიჭებენ. განსაკუთრებულ როლს ასრულებენ კეთილშობილი ობის სოკოები:</p>
      <ul>
        <li><strong>ყველი როკფორი (ცისფერი ყველი):</strong> მის შიგნით სპეციალურად შეჰყავთ ობის სოკო <em>Penicillium roqueforti</em>, რომელიც ყველის შიგნით იზრდება და ლურჯ-მომწვანო ზოლებსა და პიკანტურ არომატს წარმოქმნის.</li>
        <li><strong>ყველი კამემბერი და ბრი:</strong> მათ ზედაპირზე ვითარდება თეთრი ობის ხავერდოვანი გარსი (<em>Penicillium camemberti</em>), რომელიც შლის რძის ცილებსა და ცხიმებს, რის გამოც ყველი საოცრად რბილი და კრემისებრი ხდება.</li>
      </ul>
      <p>ეს სპეციალური კულტურული ობი ადამიანის ჯანმრთელობისთვის სრულიად უვნებელი და სასარგებლოა!</p>
    `,
