            <tr>
              <td><strong>აბედა სოკო</strong></td>
              <td>ხე-მცენარეებს</td>
              <td>ხის ტანზე ჩნდება მკვრივი, ჩლიქისებრი „თაროები“. ჰიფები შლიან ხის მერქანს, იწვევენ მის ლპობას და წაქცევას.</td>
            </tr>
            <tr>
